using System.Security.Cryptography;
using System.Text;
using TerraRuntime.Contracts.Gameplay;
using TerraRuntime.Core;
using TerraRuntime.World;
using TerraRuntime.WorldGeneration.Vanilla;

namespace TerraRuntime.Tests;

public sealed class GenerationTrackFraming1458Tests
{
    [Theory]
    [InlineData(0, false, "8E31B13F4FBEC37C782BD0A83604BEF8A5BE5BC4E7A0916D692593BD05CFB609")]
    [InlineData(0, true, "8E31B13F4FBEC37C782BD0A83604BEF8A5BE5BC4E7A0916D692593BD05CFB609")]
    [InlineData(1, false, "8E31B13F4FBEC37C782BD0A83604BEF8A5BE5BC4E7A0916D692593BD05CFB609")]
    [InlineData(1, true, "8E31B13F4FBEC37C782BD0A83604BEF8A5BE5BC4E7A0916D692593BD05CFB609")]
    [InlineData(2, false, "8E31B13F4FBEC37C782BD0A83604BEF8A5BE5BC4E7A0916D692593BD05CFB609")]
    [InlineData(2, true, "8E31B13F4FBEC37C782BD0A83604BEF8A5BE5BC4E7A0916D692593BD05CFB609")]
    public void Track_caller_matches_actual_original_for_all_masks_front_back_kinds_and_raw_neighbour_activity(
        int neighbourState, bool resetFrame, string expected)
    {
        // Actual untouched original Minecart.FrameTrack and WorldGen.TileFrame were both called
        // for64masks x37front x37back =87,616cases per profile; center frame projections agree.
        var workspace = new Workspace(80, 80);
        var random = new RandomAdapter(1458);
        var framer = new GenerationTileFraming1458(workspace.TileStore, random);
        Put(workspace, 40, 40, 314, true);
        var results = new StringBuilder();
        for (int mask = 0; mask < 64; mask++)
        {
            for (int side = 0; side < 2; side++)
            for (int row = 0; row < 3; row++)
            {
                int bit = side * 3 + row;
                Put(workspace, 40 + (side == 0 ? -1 : 1), 39 + row,
                    (mask & (1 << bit)) != 0 ? (ushort)314 : (ushort)0, neighbourState != 1,
                    actuated: neighbourState == 2);
            }
            for (short front = -1; front < 36; front++)
            for (short back = -1; back < 36; back++)
            {
                ref WorldTile center = ref At(workspace, 40, 40);
                center.FrameX = front;
                center.FrameY = back;
                framer.TileFrame(40, 40, resetFrame);
                results.Append(mask).Append(',').Append(front).Append(',').Append(back).Append(',')
                    .Append(center.FrameX).Append(',').Append(center.FrameY).Append(';');
            }
        }
        Assert.Equal(expected, Hash(results.ToString()));
        Assert.Equal("511931AF068F0673225AD8F7DE74437E97374E2890E34F8E887387CFFB6CDA29", random.Fingerprint());
        Assert.Equal(906992634, random.Next());
    }

