    public void Track_rope_endpoint_callbacks_preserve_the_below_type_quirk_range_and_inactive_shape_cleanup(
        string profile, ushort above, ushort below, bool aboveActive, bool belowActive, int range,
        string before, string after)
    {
        // Source snapshots cover every80x80cell including independent halfbrick+slope,
        // block/wall paint and all four coatings. Inactive endpoint framing clears only block state.
        _ = profile;
        var workspace = new Workspace(80, 80);
        Put(workspace, 40, 40, 314, true);
        At(workspace, 40, 40).FrameX = 33;
        At(workspace, 40, 40).FrameY = 35;
        for (int y = 34; y <= 46; y++)
        {
            if (y == 40) continue;
            ref WorldTile tile = ref At(workspace, 40, y);
            Assert.True(tile.TrySetSourceShape(true, 3));
            tile.TileColor = 5;
            tile.WallColor = 7;
            tile.Flags |= WorldTileFlags.InvisibleBlock | WorldTileFlags.FullbrightBlock |
                WorldTileFlags.InvisibleWall | WorldTileFlags.FullbrightWall;
        }
        Put(workspace, 40, 39, above, aboveActive);
        Put(workspace, 40, 41, below, belowActive);
        if (range != 0)
        {
            for (int distance = 1; distance <= 6; distance++)
                Put(workspace, 40, 40 - distance, 1, true);
            Put(workspace, 40, 40 - range, 213, true);
        }
        Assert.Equal(before, FullState(workspace));
        var random = new RandomAdapter(1458);
        new GenerationTileFraming1458(workspace.TileStore, random).TileFrame(40, 40);
        Assert.Equal(after, FullState(workspace));
        Assert.Equal("511931AF068F0673225AD8F7DE74437E97374E2890E34F8E887387CFFB6CDA29", random.Fingerprint());
        Assert.Equal(906992634, random.Next());
        for (int y = 34; y <= 46; y++)
            Assert.True(At(workspace, 40, y).HasValidSourceShape);
    }

    private static void Put(Workspace workspace, int x, int y, ushort type, bool active, bool actuated = false)
    {
        ref WorldTile tile = ref At(workspace, x, y);
        tile.Type = type;
        tile.Flags = (tile.Flags & ~(WorldTileFlags.Active | WorldTileFlags.Inactive)) |
            (active ? WorldTileFlags.Active : WorldTileFlags.None) |
            (actuated ? WorldTileFlags.Inactive : WorldTileFlags.None);
    }

    private static ref WorldTile At(Workspace workspace, int x, int y) =>
        ref workspace.TileStore.Tiles[workspace.TileStore.GetUncheckedIndex(x, y)];

    private static string Hash(string value) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value)));

    private static string FullState(Workspace workspace)
    {
        var text = new StringBuilder();
        for (int x = 0; x < 80; x++)
        for (int y = 0; y < 80; y++)
        {
            WorldTile t = At(workspace, x, y);
            text.Append(t.IsActive ? 1 : 0).Append(',').Append(t.Type).Append(',').Append(t.Wall).Append(',')
                .Append(t.FrameX).Append(',').Append(t.FrameY).Append(',').Append(t.LiquidAmount).Append(',')
                .Append(t.IsHalfBrick ? 1 : 0).Append(',').Append(t.SourceSlope).Append(',').Append(t.TileColor).Append(',')
                .Append(t.WallColor).Append(',').Append((t.Flags & WorldTileFlags.InvisibleBlock) != 0 ? 1 : 0).Append(',')
                .Append((t.Flags & WorldTileFlags.FullbrightBlock) != 0 ? 1 : 0).Append(',')
                .Append((t.Flags & WorldTileFlags.InvisibleWall) != 0 ? 1 : 0).Append(',')
                .Append((t.Flags & WorldTileFlags.FullbrightWall) != 0 ? 1 : 0).Append(',').Append(t.IsActuated ? 1 : 0).Append(';');
        }
        return Hash(text.ToString());
    }

    private sealed class RandomAdapter(int seed) : IWorldGenerationVanillaRandom
    {
        private readonly VanillaUnifiedRandom1458 random = new(seed);
        public string Fingerprint()
        {
            const System.Reflection.BindingFlags flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
            var cursor = typeof(VanillaUnifiedRandom1458).GetField("inext", flags)!.GetValue(random);
            var slots = (int[])typeof(VanillaUnifiedRandom1458).GetField("seedArray", flags)!.GetValue(random)!;
            return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(cursor + ";" + string.Join(",", slots))));
        }
        public int Next() => random.Next();
        public int Next(int maxValue) => random.Next(maxValue);
        public int Next(int minValue, int maxValue) => random.Next(minValue, maxValue);
        public double NextDouble() => random.NextDouble();
        public void NextBytes(byte[] buffer) => random.NextBytes(buffer);
    }
}
